<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/research-knowledge.php';require_once __DIR__.'/app/research-workspace.php';
$u=require_user($pdo);$id=(string)($_GET['id']??$_POST['id']??'');$finding=research_finding_access($pdo,$u,$id);if(!$finding){http_response_code(404);exit('Research finding not found.');}$canWrite=project_can_write($finding);$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=(string)($_POST['op']??'');try{
    if(!$canWrite)throw new RuntimeException('You have view-only access to this project.');
    if($op==='update'){
        $title=trim((string)($_POST['title']??''));$summary=trim((string)($_POST['summary']??''));if($title===''||$summary==='')throw new RuntimeException('Finding title and summary are required.');
        $status=(string)($_POST['status']??'draft');if(!in_array($status,['draft','final','archived'],true))$status='draft';
        $pdo->prepare('UPDATE research_findings SET title=?,summary=?,status=? WHERE id=?')->execute([$title,$summary,$status,$finding['id']]);$success='Finding updated.';
    }
    if($op==='add_claim'){
        $claimPublic=trim((string)($_POST['claim_id']??''));$relationship=(string)($_POST['relationship']??'supports');if(!in_array($relationship,['primary','supports','contradicts','context'],true))$relationship='supports';$position=max(0,(int)($_POST['position']??0));
        $q=$pdo->prepare('SELECT id FROM research_claims WHERE public_id=? AND project_id=?');$q->execute([$claimPublic,$finding['project_id']]);$claimId=(int)($q->fetchColumn()?:0);if(!$claimId)throw new RuntimeException('That Claim is not in this Research project.');
        $pdo->prepare('INSERT INTO finding_claims(finding_id,claim_id,added_by_user_id,relationship,position) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE relationship=VALUES(relationship),position=VALUES(position),added_by_user_id=VALUES(added_by_user_id)')->execute([$finding['id'],$claimId,$u['id'],$relationship,$position]);$success='Claim added to Finding.';
    }
    if($op==='remove_claim'){$claimPublic=(string)($_POST['claim']??'');$pdo->prepare('DELETE fc FROM finding_claims fc JOIN research_claims rc ON rc.id=fc.claim_id WHERE fc.finding_id=? AND rc.public_id=?')->execute([$finding['id'],$claimPublic]);$success='Claim removed from Finding.';}
    if($success!==''&&function_exists('data_attribution_capture_object'))data_attribution_capture_object($pdo,(int)$u['id'],'finding',(string)$finding['public_id']);
    if($success!==''&&research_workspace_ready($pdo))research_workspace_queue($pdo,(int)$finding['project_id'],3);
}catch(Throwable $e){$error=$e->getMessage();}
$finding=research_finding_access($pdo,$u,$id)??$finding;}
$claims=research_finding_claim_rows($pdo,(int)$finding['id']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($finding['title'])?> · Finding · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body data-workspace-user="<?=h((string)$u['public_id'])?>" data-workspace-surface="research" data-workspace-research="<?=h((string)$finding['project_public_id'])?>" data-workspace-object-type="finding" data-workspace-object="<?=h((string)$finding['public_id'])?>"><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/research-project.php?id=<?=h($finding['project_public_id'])?>">Project</a><a href="/research.php">Research</a></nav></header><main class="layout"><section><div class="pageTitle"><span class="eyebrow">FINDING · <?=h(strtoupper($finding['status']))?></span><h1><?=h($finding['title'])?></h1><p><?=nl2br(h($finding['summary']))?></p><div class="inlineActions"><?php if($canWrite):?><a class="button secondary" href="/research-reviews.php?type=finding&subject=<?=h($finding['public_id'])?>">Request Review</a><?php endif?><a class="button secondary" href="/research-reviews.php">Review Center</a></div></div><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<h2>Claims</h2><?php if(!$claims):?><div class="card empty">No Claims linked yet.</div><?php endif?><?php foreach($claims as $c):?><article class="card"><div class="meta"><?=h(strtoupper($c['relationship']))?> · <?=h($c['claim_type'])?> · <?=h($c['status'])?></div><h3><a href="/research-claim.php?id=<?=h($c['public_id'])?>"><?=h($c['statement'])?></a></h3><?php if($canWrite):?><form method="post" class="inlineForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($finding['public_id'])?>"><input type="hidden" name="op" value="remove_claim"><input type="hidden" name="claim" value="<?=h($c['public_id'])?>"><button>Remove</button></form><?php endif?></article><?php endforeach?></section><aside><?php if($canWrite):?><div class="card"><h3>Edit finding</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($finding['public_id'])?>"><input type="hidden" name="op" value="update"><label>Title<input name="title" value="<?=h($finding['title'])?>" required></label><label>Summary<textarea name="summary" rows="8" required><?=h($finding['summary'])?></textarea></label><label>Status<select name="status"><?php foreach(['draft','final','archived'] as $v):?><option value="<?=h($v)?>" <?=$finding['status']===$v?'selected':''?>><?=h(ucfirst($v))?></option><?php endforeach?></select></label><button>Save finding</button></form></div><div class="card"><h3>Add Claim</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($finding['public_id'])?>"><input type="hidden" name="op" value="add_claim"><label>Claim ID<input name="claim_id" required placeholder="Paste Claim ID"></label><label>Relationship<select name="relationship"><option value="primary">Primary</option><option value="supports">Supports</option><option value="contradicts">Contradicts</option><option value="context">Context</option></select></label><label>Order<input type="number" min="0" name="position" value="0"></label><button>Add Claim</button></form></div><?php endif?></aside></main><script src="/assets/js/workspace-state.js?v=34.0"></script></body></html>
